def add(state, arguments):
    return {'total': state['total'] + arguments['amount']}

result = run_tool_session(
    {'total': 1},
    {'add': add},
    [
        {'type': 'tool', 'name': 'add', 'arguments': {'amount': 2}},
        {'type': 'tool', 'name': 'add', 'arguments': {'amount': 4}},
        {'type': 'final', 'answer': 'done'},
    ],
    max_calls=3,
)
assert result == {
    'state': {'total': 7},
    'transcript': [
        {'name': 'add', 'arguments': {'amount': 2}, 'updates': {'total': 3}},
        {'name': 'add', 'arguments': {'amount': 4}, 'updates': {'total': 7}},
    ],
    'status': 'complete',
    'answer': 'done',
}

original = {'items': ['kept']}
def mutate_copy(state, arguments):
    state['items'].append(arguments['value'])
    return {'observed': list(state['items'])}
def must_not_run(state, arguments):
    raise AssertionError('action after final must not run')

result = run_tool_session(
    original,
    {'mutate': mutate_copy, 'never': must_not_run},
    [
        {'type': 'tool', 'name': 'mutate', 'arguments': {'value': 'local'}},
        {'type': 'final', 'answer': {'ok': True}},
        {'type': 'tool', 'name': 'never', 'arguments': {}},
    ],
    max_calls=2,
)
assert original == {'items': ['kept']}
assert result['state'] == {'items': ['kept'], 'observed': ['kept', 'local']}
assert result['answer'] == {'ok': True}

incomplete = run_tool_session({}, {}, [], max_calls=1)
assert incomplete == {'state': {}, 'transcript': [], 'status': 'incomplete', 'answer': None}

def noop(state, arguments):
    return {}

def must_raise(kind, call):
    try:
        call()
    except (kind, AssertionError):
        return
    raise AssertionError('expected exception')
must_raise(ValueError, lambda: run_tool_session({}, {}, [{'type': 'tool', 'name': 'missing', 'arguments': {}}], 1))
must_raise(RuntimeError, lambda: run_tool_session({}, {'noop': noop}, [{'type': 'tool', 'name': 'noop', 'arguments': {}}, {'type': 'tool', 'name': 'noop', 'arguments': {}}], 1))
must_raise(ValueError, lambda: run_tool_session({}, {}, [], 0))

arguments = {'nested': {'items': ['kept']}}
actions = [{'type': 'tool', 'name': 'mutate', 'arguments': arguments}, {'type': 'final', 'answer': None}]
def mutate(state, received):
    received['nested']['items'].append('tool-local')
    return {'observed': received['nested']['items']}
result = run_tool_session({}, {'mutate': mutate}, actions, max_calls=1)
assert arguments == {'nested': {'items': ['kept']}}
assert result['state'] == {'observed': ['kept', 'tool-local']}
assert result['transcript'][0]['arguments'] == arguments
assert result['status'] == 'complete' and result['answer'] is None

def expect_invalid(call):
    try:
        call()
    except (AssertionError, ValueError, TypeError):
        return
    raise AssertionError('expected invalid session')
for action in ({'type': 'final'}, {'type': 'unknown'}, {'type': 'tool', 'name': 'bad', 'arguments': []}):
    expect_invalid(lambda action=action: run_tool_session({}, {'bad': lambda state, args: {}}, [action], 1))
expect_invalid(lambda: run_tool_session({}, {}, [], True))
expect_invalid(lambda: run_tool_session({}, {'bad': lambda state, args: []}, [{'type': 'tool', 'name': 'bad', 'arguments': {}}], 1))
